namespace SmartCampus.Bookings.Api.Features.Notifications;

/// <summary>
/// Sends notification emails generated by other modules.
/// Implemented using a pickup directory: each delivery becomes a .eml file,
/// never a transmission to a real SMTP server.
/// </summary>
public interface INotificationSender
{
    Task SendAsync(OutgoingEmail email, CancellationToken cancellationToken = default);
}
